const formData    = $('Get Form Context').first().json || {};
const leadData    = $('Get Lead Details').first().json || {};
const profileData = $('Get Consultant Profile').first().json || {};
const webhookData = $('Merge Triggers').first().json.body || {};

let agentData = null;
try { agentData = $('Get Agent Focus').first()?.json; } catch(e) {}

// ── Persona assembly (v2) ──
// Layer 1: Consultant identity
let persona = `<consultant_identity>\nNom : ${profileData.full_name || 'le consultant'}\nMétier : ${profileData.job_title || 'Business Consultant'}\nSite : ${profileData.website || 'Non renseigné'}\n</consultant_identity>\n`;

// Layer 2: Consultant custom directives (from form ai_config)
if (formData.ai_config?.systemPrompt) {
  persona += `<consultant_directives>\n${formData.ai_config.systemPrompt}\n</consultant_directives>\n`;
}

// Layer 3: Agent mission (from agents_library.base_prompt) — overrides generic if present
if (agentData?.base_prompt) {
  persona += `<agent_mission>\n${agentData.base_prompt}\n</agent_mission>\n`;
} else {
  persona += `<agent_mission>\nTu es un consultant stratégique généraliste. Analyse la situation du prospect avec rigueur, identifie les risques concrets liés à l\'inaction, et structure un audit qui démontre ton expertise sectorielle. Adapte ton vocabulaire et tes KPIs au domaine du consultant.\n</agent_mission>\n`;
}

// ── Input quality signal (for anti-bullshit protocol) ──
const staticStr = JSON.stringify(leadData.static_answers || {});
const dynamicStr = JSON.stringify(leadData.dynamic_answers || {});
const totalInputWords = (staticStr + ' ' + dynamicStr).split(/\s+/).length;
const inputQuality = totalInputWords < 30 ? 'LOW' : totalInputWords < 80 ? 'MEDIUM' : 'HIGH';

// ── Website URL extraction ──
let website_url = leadData.website_url || '';
if (!website_url && leadData.static_answers) {
  for (const [key, value] of Object.entries(leadData.static_answers)) {
    if (typeof value === 'string' && (value.includes('http') || value.includes('www.'))) {
      website_url = value; break;
    }
  }
}

// ── Sector extraction — multi-language keys ──
const sectorKeys = ['secteur', 'sector', 'industry', 'industrie', 'domaine', 'domain', 'قطاع', 'branche'];
let sector = leadData.sector || 'B2B Services';
if (leadData.static_answers) {
  for (const key of sectorKeys) {
    if (leadData.static_answers[key]) { sector = leadData.static_answers[key]; break; }
  }
  if (sector === 'B2B Services') {
    for (const [k, v] of Object.entries(leadData.static_answers)) {
      if (typeof v === 'string' && v.length < 60 && !v.includes('http') && 
          (k.toLowerCase().includes('sect') || k.toLowerCase().includes('ind') || k.toLowerCase().includes('dom'))) {
        sector = v; break;
      }
    }
  }
}

// ── Service name ──
const serviceName = agentData?.name || formData.title || 'the service';

// ── Consultant contact ──
const consultantName    = profileData.full_name    || 'the consultant';
const consultantWebsite = profileData.website      || '';
const consultantLanguage = profileData.language    || 'Français';
const consultantJob     = profileData.job_title    || 'Consultant';

return [{
  json: {
    lead_id:           leadData.id,
    lead_email:        leadData.email        || '',
    lead_company:      leadData.company      || leadData.full_name || 'the prospect',
    website_url,
    sector,
    service_name:      serviceName,
    static_answers:    staticStr,
    dynamic_answers:   dynamicStr,
    input_quality:     inputQuality,
    action:            webhookData.action,
    feedback:          webhookData.feedback  || '',
    consultant_language: consultantLanguage,
    consultant_job:    consultantJob,
    consultant_name:   consultantName,
    consultant_website: consultantWebsite,
    consultant_booking_url: profileData.booking_config?.external_url || profileData.website || '',
    persona,
    history:           leadData.ai_generation_history || []
  }
}];

