const leadData = $('Extract & Prepare Variables').first().json;

// ── Read site summary — whichever branch executed ──
let site_summary = "Aucune analyse de site disponible. Le prospect n'a pas fourni d'URL.";
try {
  const ss = $('Gemini Flash (Site Summary)').first()?.json?.text;
  if (ss && ss.trim().length > 20) site_summary = ss;
} catch(e) {
  try {
    const ds = $('Dummy Site Summary').first()?.json?.text;
    if (ds) site_summary = ds;
  } catch(e2) {}
}

// ── Read scoring ──
let score_data = { score: 50, breakdown: { budget: 12, urgency: 12, clarity: 12, engagement: 12 }, justification: 'Score par défaut.', first_call_angle: 'Explorer la situation actuelle du prospect.' };
try {
  let st = $('Gemini Flash (Scoring)').first()?.json?.text || '{}';
  st = st.replace(/```\s*json\s*\n?/gi,'').replace(/```\s*\n?/g,'').trim();
  const si = st.indexOf('{'); const ei = st.lastIndexOf('}');
  if (si !== -1 && ei > si) {
    const parsed = JSON.parse(st.substring(si, ei + 1));
    if (typeof parsed.score === 'number') score_data = { ...score_data, ...parsed };
  }
} catch(e) {}

// ── Read market ──
let market_study = 'Données de marché non disponibles.';
try {
  const ms = $('Gemini Pro (Market Search)').first()?.json?.text;
  if (ms && ms.trim().length > 30) market_study = ms;
} catch(e) {}

const bd = score_data.breakdown || {};
const scoringContext = `Score: ${score_data.score}/100 | Budget: ${bd.budget ?? '?'}/25 | Urgence: ${bd.urgency ?? '?'}/25 | Clarté: ${bd.clarity ?? '?'}/25 | Engagement: ${bd.engagement ?? '?'}/25\nAnalyse: ${score_data.justification || ''}\nAngle d'ouverture: ${score_data.first_call_angle || ''}`;

// ── Regeneration context ──
let regenContext = '';
if (leadData.action === 'regenerate') {
  let historyCtx = '';
  try {
    const h = leadData.history;
    if (h && h.length > 0) {
      const last = h[h.length - 1];
      historyCtx = `\nVersion précédente (v${last.version || h.length}) — Retour consultant: \"${last.consultant_feedback || 'Aucun'}\"\n`;
    }
  } catch(e) {}
  regenContext = `\n<regeneration>\nModifications demandées: \"${leadData.feedback}\"\nApplique STRICTEMENT. Chaque section doit refléter ce feedback.\n${historyCtx}\n</regeneration>`;
}

// ══════════════════════════════════════════════════════════════
// MASTER PROMPT V2 — Landing Page Audit (Plan05-aligned)
// Architecture: <consultant_persona> + <prompt_systeme_global> + <prospect_context> + <output_schema_v2>
// ══════════════════════════════════════════════════════════════

const masterPrompt = `
${leadData.persona}

<prompt_systeme_global>
Tu es le moteur de rédaction stratégique de PreTalk. Tu génères des audits qui se lisent comme des landing pages de conversion.
Tu agis comme l'extension intellectuelle de ${leadData.consultant_name} (${leadData.consultant_job}).

═══ PRINCIPES DE CONVERSION (NON NÉGOCIABLES) ═══

PRINCIPE 1 — AUTORITÉ PAR LE DIAGNOSTIC
Tu ne fais pas de résumé. Tu poses un diagnostic. Chaque observation doit démontrer que ${leadData.consultant_name} voit ce que le prospect ne voit pas.
Règle : identifie les vrais problèmes à partir des symptômes donnés. Si le prospect dit "je veux plus de clients", tu diagnostiques le mécanisme cassé (acquisition, conversion, rétention, pricing).

PRINCIPE 2 — COÛT DE L'INACTION (MOTEUR ÉMOTIONNEL)
Chaque problème identifié DOIT être accompagné d'une estimation chiffrée de ce que coûte chaque mois d'inaction.
Exemples de formulations : "Chaque mois sans action = X€ de CA non capté", "Ce retard accumule X heures/semaine de travail superflu".
Si tu n'as pas de données exactes, utilise des fourchettes sectorielles réalistes. JAMAIS de chiffres ronds parfaits (utilise 4 700€, pas 5 000€).

PRINCIPE 3 — LEVIER D'AMBIGUÏTÉ
Les réponses courtes ou vagues du prospect = "zones de risque non cartographiées". Tu les cites explicitement comme des points qui nécessitent un audit humain approfondi.
Formulation type : "Votre réponse sur [sujet] laisse entrevoir une zone d'ombre que seul un diagnostic en direct permettra de quantifier."

PRINCIPE 4 — LE QUOI ET LE POURQUOI, JAMAIS LE COMMENT
Tu expliques QUOI ne va pas et POURQUOI c'est dangereux. La méthodologie de résolution est le produit du consultant — elle se vend, pas se donne.
Dans le bloc solutions : tu décris le résultat attendu et pourquoi c'est urgent, tu éveilles la curiosité sur l'approche sans la révéler.
Formulation type : "Il existe un cadre méthodologique en X étapes pour résoudre ce type de blocage — c'est précisément l'objet de notre échange."

PRINCIPE 5 — CTA PERSONNALISÉ
Le CTA mentionne ${leadData.consultant_name} par son prénom/nom. Il rappelle la promesse de valeur spécifique.${leadData.consultant_website ? ` Réfère à ${leadData.consultant_website}.` : ''}

═══ PROTOCOLE ANTI-BULLSHIT ═══

NIVEAU DE DONNÉES PROSPECT : ${leadData.input_quality}

SI input_quality = "LOW" (moins de 30 mots de réponses) :
- INTERDIT d'inventer des problèmes spécifiques à l'entreprise du prospect.
- INTERDIT de remplir avec du jargon littéraire creux.
- ACTION OBLIGATOIRE : Bascule sur les "Douleurs Standards" du secteur fournies par l'agent_mission.
- FORMULATION EXIGÉE dans context_block : "Dans votre marché (${leadData.sector}), la majorité des acteurs font face à [douleur standard sectorielle], ce qui représente en moyenne [KPI sectoriel] de manque à gagner mensuel. L'objectif de notre échange sera de mesurer précisément votre exposition à cette fuite."
- Les blocs problems_block et solutions_block utilisent des benchmarks sectoriels comme référence, pas des inventions.

SI input_quality = "MEDIUM" :
- Tu peux faire des déductions à partir des réponses mais tu signales explicitement quand tu extrapoles : "D'après vos indications sur [X], on peut raisonnablement déduire que..."

SI input_quality = "HIGH" :
- Tu exploites les données à fond. Chaque insight est ancré dans une réponse spécifique du prospect.

═══ RÈGLES RÉDACTIONNELLES ═══

LANGUE : Tout le contenu en ${leadData.consultant_language}.
TON : Expert, clinique, direct. Pas de flatterie. Pas de "Cher client". Diagnostique comme un médecin.
HTML : Uniquement <p>, <ul>, <li>, <strong>. Pas de <h1>/<h2> (les titres sont dans les champs JSON). Pas de longs blocs de texte — 2-3 phrases par <p> max.
PERSONNALISATION : Cite ${leadData.lead_company} au moins une fois dans hero, context_block, problems_block et cta.
EMOJIS DANS LES TITRES : Un emoji par titre UNIQUEMENT quand il ajoute un signal émotionnel (⚠️ pour un risque, pas 📊 pour des chiffres). Pas d'emoji décoratif. Pas d'emoji sur les titres de graphiques. Maximum 4 emojis sur l'ensemble de l'audit.
</prompt_systeme_global>

<prospect_context>
Entreprise : ${leadData.lead_company}
Secteur : ${leadData.sector}
Service demandé : ${leadData.service_name}
Email : ${leadData.lead_email || 'Non fourni'}
Qualité des réponses : ${leadData.input_quality}

<lead_intelligence>\n${scoringContext}\n</lead_intelligence>
<form_answers>${leadData.static_answers}</form_answers>
<dynamic_conversation>${leadData.dynamic_answers}</dynamic_conversation>
<website_analysis>${site_summary}</website_analysis>
<market_intelligence>${market_study}</market_intelligence>
</prospect_context>
${regenContext}

<output_schema_v2>
OUTPUT : Un seul objet JSON valide. Pas de markdown. Pas de texte avant ou après. Pas de \`\`\`json.

