const response = $input.first().json;
let content = response.text || '{}';

// Strip reasoning tags and markdown fences
content = content.replace(/<thinking>[\s\S]*?<\/thinking>/gi, '').trim();
content = content.replace(/```\s*json\s*\n?/gi, '').replace(/```\s*\n?/g, '').trim();

// Robust JSON extraction
const s = content.indexOf('{');
const e = content.lastIndexOf('}');
if (s !== -1 && e > s) content = content.substring(s, e + 1);

let analysis;
try {
  analysis = JSON.parse(content);
} catch (err) {
  throw new Error('AUDIT_PARSE_ERROR: Gemini returned invalid JSON. Raw: ' + content.substring(0, 500));
}

// ══════════════════════════════════════════════════
// V2 SCHEMA VALIDATION & NORMALIZATION
// ══════════════════════════════════════════════════

// Force version
analysis.version = 2;

// ── hero ──
if (!analysis.hero || typeof analysis.hero !== 'object') {
  throw new Error('AUDIT_SCHEMA_ERROR: hero block missing in output.');
}
analysis.hero.score = typeof analysis.hero.score === 'number' ? Math.min(100, Math.max(0, Math.round(analysis.hero.score))) : 50;
analysis.hero.headline = String(analysis.hero.headline || 'Votre audit personnalisé');
analysis.hero.subline = String(analysis.hero.subline || '');
analysis.hero.score_label = String(analysis.hero.score_label || 'Score global');

// ── context_block ──
if (!analysis.context_block || typeof analysis.context_block !== 'object') {
  analysis.context_block = { title: 'Votre situation', content: '<p>Analyse en cours...</p>', highlights: [] };
}
if (!Array.isArray(analysis.context_block.highlights)) analysis.context_block.highlights = [];
analysis.context_block.highlights = analysis.context_block.highlights.slice(0, 3).map(h => String(h));

// ── checklist ──
if (!analysis.checklist || !Array.isArray(analysis.checklist.items)) {
  analysis.checklist = { title: 'Points de contrôle', items: [] };
}
analysis.checklist.items = analysis.checklist.items
  .filter(i => i && i.label)
  .map(i => ({ label: String(i.label), status: ['missing','partial','ok'].includes(i.status) ? i.status : 'partial' }));

// ── visualizations ──
if (!Array.isArray(analysis.visualizations)) analysis.visualizations = [];
analysis.visualizations = analysis.visualizations
  .filter(v => v && typeof v === 'object')
  .map((v, idx) => ({
    id: String(v.id || `viz-${idx + 1}`),
    type: ['bar','radar','line','table'].includes(String(v.type || '').toLowerCase()) ? String(v.type).toLowerCase() : 'bar',
    title: String(v.title || `Visualisation ${idx + 1}`),
    label_unite: String(v.label_unite || '€'),
    enabled: v.enabled !== false,
    points: Array.isArray(v.points)
      ? v.points.filter(p => p && typeof p.label === 'string').map(p => ({ label: String(p.label), value: Number.isFinite(Number(p.value)) ? Number(p.value) : 0 }))
      : []
  }))
  .filter(v => v.points.length > 0);

// Ensure at least 2 visualizations with safe defaults
if (analysis.visualizations.length === 0) {
  analysis.visualizations = [
    { id: 'viz-cost', type: 'bar', title: 'Impact financier estimé', label_unite: '€', enabled: true, points: [{ label: 'Coût inaction (6 mois)', value: 8500 }, { label: 'Potentiel optimisé', value: 28000 }] },
    { id: 'viz-maturity', type: 'radar', title: 'Maturité par axe', label_unite: '/100', enabled: true, points: [{ label: 'Stratégie', value: 50 }, { label: 'Exécution', value: 50 }, { label: 'Ressources', value: 50 }, { label: 'Opportunités', value: 50 }] }
  ];
}

// ── analysis_block ──
if (!analysis.analysis_block || typeof analysis.analysis_block !== 'object') {
  analysis.analysis_block = { title: 'Résultats de l\'analyse', content: '<p>Analyse non disponible.</p>' };
}

// ── problems_block ──
if (!analysis.problems_block || !Array.isArray(analysis.problems_block.items)) {
  analysis.problems_block = { title: 'Problèmes identifiés', items: [] };
}
analysis.problems_block.items = analysis.problems_block.items
  .filter(i => i && i.title)
  .map(i => ({
    title: String(i.title),
    description: String(i.description || ''),
    severity: ['critical','high','medium'].includes(i.severity) ? i.severity : 'medium'
  }));

// ── solutions_block ──
if (!analysis.solutions_block || !Array.isArray(analysis.solutions_block.items)) {
  analysis.solutions_block = { title: 'Axes de résolution', items: [] };
}
analysis.solutions_block.items = analysis.solutions_block.items
  .filter(i => i && i.title)
  .map(i => ({
    title: String(i.title),
    description: String(i.description || ''),
    impact: ['Fort','Moyen'].includes(i.impact) ? i.impact : 'Moyen'
  }));

// ── cta ──
if (!analysis.cta || typeof analysis.cta !== 'object') {
  analysis.cta = { headline: 'Passez à l\'action', sublabel: '', cta_label: 'Réserver mon appel', booking_url: '' };
}

// ── consultant_edits (initialized empty for consultant-side editing) ──
if (!analysis.consultant_edits || typeof analysis.consultant_edits !== 'object') {
  analysis.consultant_edits = {
    block_images: {},
    block_visibility: {},
    block_order: ['hero', 'context_block', 'checklist', 'visualizations', 'analysis_block', 'problems_block', 'solutions_block', 'cta']
  };
}

// ── Backward compat: remove deprecated v1 fields if LLM still generates them ──
delete analysis.audit_blocks;
delete analysis.chart_data;
delete analysis.client_graph;

// ── Extract score from scoring branch ──
let final_score = analysis.hero.score;
try {
  let st = $('Prepare Master Prompt').first().json.score_json || '{}';
  st = st.replace(/```\s*json\s*\n?/gi,'').replace(/```\s*\n?/g,'').trim();
  const si = st.indexOf('{'); const ei = st.lastIndexOf('}');
  if (si !== -1 && ei > si) {
    const so = JSON.parse(st.substring(si, ei+1));
    if (typeof so.score === 'number' && so.score >= 0 && so.score <= 100) {
      final_score = so.score;
      analysis.hero.score = final_score;
    }
  }
} catch(e) {}

return [{
  json: {
    ai_analysis_json: JSON.stringify(analysis),
    score: final_score,
    id: $('Prepare Master Prompt').first().json.lead_id
  }
}];
